mutations.find:
def validate_surface(surface: str) -> str:
    """Return a validated audit surface token."""
    if not SURFACE_RE.match(surface) or PASS_INDEX_RE.match(surface):
        raise ValueError(f"invalid surface token: {surface!r}")
    return surface

